package did

import (
	"encoding/json"
	"os"
	"path/filepath"
	"testing"
)

// pqFixture is generated by bigtangle-ts PQKey (see the dai repo's
// packages/did test fixtures) so the Go verifier and the wallet signer cannot
// drift.
type pqFixture struct {
	Seed      string `json:"seed"`
	DID       string `json:"did"`
	Nonce     string `json:"nonce"`
	SigBundle string `json:"sigBundle"`
}

func loadPQFixture(t *testing.T) pqFixture {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("testdata", "mldsa87_challenge.json"))
	if err != nil {
		t.Fatalf("read fixture: %s", err)
	}
	var fixture pqFixture
	if err := json.Unmarshal(raw, &fixture); err != nil {
		t.Fatalf("parse fixture: %s", err)
	}
	return fixture
}

func TestVerifyPQSignatureFixture(t *testing.T) {
	fixture := loadPQFixture(t)

	if !IsValidPQDID(fixture.DID) {
		t.Fatalf("fixture DID should be valid: %s", fixture.DID)
	}
	if !VerifyPQSignature(fixture.DID, fixture.Nonce, fixture.SigBundle) {
		t.Fatal("bigtangle-ts fixture signature should verify with circl")
	}
	if VerifyPQSignature(fixture.DID, "00"+fixture.Nonce[2:], fixture.SigBundle) {
		t.Fatal("wrong nonce should fail")
	}

	tampered := fixture.SigBundle[:len(fixture.SigBundle)-2] + "00"
	if VerifyPQSignature(fixture.DID, fixture.Nonce, tampered) {
		t.Fatal("tampered signature should fail")
	}
}

func TestVerifyPQSignatureRejectsMalformed(t *testing.T) {
	fixture := loadPQFixture(t)

	if VerifyPQSignature(fixture.DID, fixture.Nonce, "not-hex") {
		t.Fatal("non-hex signature should fail")
	}
	if VerifyPQSignature(fixture.DID, "zz", fixture.SigBundle) {
		t.Fatal("non-hex nonce should fail")
	}
	if VerifyPQSignature("did:key:z6Mkabc", fixture.Nonce, fixture.SigBundle) {
		t.Fatal("non-PQ DID should fail")
	}
}

func TestVerifyPQSignatureBrowserFixture(t *testing.T) {
	// Produced by the httpSMS web signer (web/app/utils/pq.ts) from the same
	// seed, proving the browser and the Go verifier agree.
	raw, err := os.ReadFile(filepath.Join("testdata", "mldsa87_browser_challenge.json"))
	if err != nil {
		t.Fatalf("read fixture: %s", err)
	}
	var fixture pqFixture
	if err := json.Unmarshal(raw, &fixture); err != nil {
		t.Fatalf("parse fixture: %s", err)
	}

	if !VerifyPQSignature(fixture.DID, fixture.Nonce, fixture.SigBundle) {
		t.Fatal("browser-generated signature should verify")
	}
}

func TestVerifyPQSignatureDualFixture(t *testing.T) {
	// Dual ML-DSA-87 + SLH-DSA-SHA2-256s key: both signatures must verify.
	raw, err := os.ReadFile(filepath.Join("testdata", "mldsa87_slhdsa_challenge.json"))
	if err != nil {
		t.Fatalf("read fixture: %s", err)
	}
	var fixture pqFixture
	if err := json.Unmarshal(raw, &fixture); err != nil {
		t.Fatalf("parse fixture: %s", err)
	}

	if !VerifyPQSignature(fixture.DID, fixture.Nonce, fixture.SigBundle) {
		t.Fatal("dual-key fixture should verify (ML-DSA-87 + SLH-DSA-SHA2-256s)")
	}
	if VerifyPQSignature(fixture.DID, "00"+fixture.Nonce[2:], fixture.SigBundle) {
		t.Fatal("wrong nonce should fail")
	}
}

func TestVerifyPQSignatureDualBrowserFixture(t *testing.T) {
	raw, err := os.ReadFile(filepath.Join("testdata", "mldsa87_slhdsa_browser_challenge.json"))
	if err != nil {
		t.Fatalf("read fixture: %s", err)
	}
	var fixture pqFixture
	if err := json.Unmarshal(raw, &fixture); err != nil {
		t.Fatalf("parse fixture: %s", err)
	}
	if !VerifyPQSignature(fixture.DID, fixture.Nonce, fixture.SigBundle) {
		t.Fatal("browser dual-key signature should verify")
	}
}

func TestIsValidPQDIDRejects(t *testing.T) {
	for _, did := range []string{"", "not-a-did", "did:key:zInvalid", "did:key:z6Mkabc"} {
		if IsValidPQDID(did) {
			t.Fatalf("expected invalid: %q", did)
		}
	}
}
